-- PT9 Math Module 2 canonical import: 27 questions.
-- Parsed from the user-provided official PT9 question PDF; answer keys/pages from the official scoring and answer-explanations PDFs.
begin;
on conflict (id) do update set
subject=excluded.subject,module=excluded.module,question_number=excluded.question_number,source_page=excluded.source_page,answer_page=excluded.answer_page,
correct_answer=excluded.correct_answer,accepted_answers=excluded.accepted_answers,response_type=excluded.response_type,question_lines=excluded.question_lines,
explanation_lines=excluded.explanation_lines,needs_visual=excluded.needs_visual,content_status=excluded.content_status,visual_crop=excluded.visual_crop,
visual_after_line=excluded.visual_after_line,practice_test_id=excluded.practice_test_id,source_crop=excluded.source_crop,question_mode=excluded.question_mode,
visual_specs=excluded.visual_specs,inline_visuals=excluded.inline_visuals,updated_at=now();

on conflict (question_id) do update set
difficulty=excluded.difficulty,concepts=excluded.concepts,reasoning_steps=excluded.reasoning_steps,integration_level=excluded.integration_level,
confidence=excluded.confidence,rubric_version=excluded.rubric_version,evaluated_at=excluded.evaluated_at;
commit;
